-- Generado por cavidades/datos/generar_sql.py. No editar a mano.
BEGIN;


VALUES ('TOR_PULMON', 'Pulmones', 'Pulmo dexter et sinister', 'Órganos de intercambio gaseoso alojados en las cavidades pleurales derecha e izquierda. En el caballo las fisuras interlobulares son poco marcadas. El pulmón izquierdo tiene lóbulos craneal y caudal, separados solo por la escotadura cardíaca; el derecho tiene lóbulos craneal, caudal y accesorio. No existe lóbulo medio diferenciado.', 'Ocupan cada hemitórax desde la abertura torácica craneal hasta el diafragma. El lóbulo accesorio del pulmón derecho se aloja en el receso mediastínico, entre el mediastino caudal y el pliegue de la vena cava caudal.', 'Campo de auscultación triangular: borde craneal en la línea tricipital, dorsal en la musculatura epiaxial y caudoventral en una línea curva que pasa por el EIC 16 a la altura de la tuberosidad coxal, el EIC 11 a la altura de la punta del hombro y el EIC 6 a la altura del olécranon.', 'Medialmente, el mediastino, el corazón (escotadura cardíaca más amplia a la izquierda, entre las costillas 3.ª y 6.ª), la tráquea y los bronquios principales. Caudal al borde basal queda el receso costodiafragmático, ocupado solo por pleura. Caudalmente, el diafragma.', 'Raíz pulmonar (bronquio principal y vasos pulmonares) y ligamento pulmonar hacia el mediastino.', 'Circulación funcional por arterias y venas pulmonares; circulación nutricia por ramas bronquiales de la arteria broncoesofágica (rama de la aorta torácica).', 'Llenan cada hemitórax; su volumen varía con la fase respiratoria. El modelo representa la espiración.', 'Pleuroneumonía (derrame frecuentemente bilateral por el mediastino fenestrado), asma equina (antes obstrucción recurrente de las vías aéreas), hemorragia pulmonar inducida por el ejercicio (afecta los campos caudodorsales) y neumotórax bilateral.', 'Auscultación y percusión en el campo pulmonar; ecografía torácica; radiografía; endoscopia y lavado broncoalveolar.', (SELECT id FROM cavidades WHERE codigo = 'toracica'), (SELECT id FROM sistemas_anatomicos WHERE codigo = 'respiratorio'), ARRAY['Dyce, Sack & Wensing 2018', 'Budras, Sack & Röck 2012', 'Reed, Bayly & Sellon (ed. reciente)']::text[], TRUE, ARRAY['medios_de_fijacion', 'irrigacion_drenaje']::text[], 'ambos')
