VALUES ('ABD_FLEXURA_PELVICA', 'Flexura pélvica', 'Flexura pelvina', 'Codo caudal del colon mayor que une el colon ventral izquierdo con el colon dorsal izquierdo. En ella el diámetro del colon se reduce bruscamente y queda una sola tenia, sin saculaciones. Su posición varía con el llenado y puede desplazarse cranealmente.', 'Caudal, a la entrada de la cavidad pélvica, en el lado izquierdo.', 'No accesible desde la superficie; se alcanza por palpación rectal.', 'Vejiga urinaria y cavidad pélvica caudalmente; colon descendente dorsalmente. Es la porción del colon mayor más accesible por vía rectal.', 'Libre, sin fijación a la pared; muy móvil.', 'Anastomosis entre las ramas cólicas de la arteria mesentérica craneal.', 'Diámetro de ≈8-9 cm en el estrechamiento.', 'Sitio más frecuente de impactación del colon por el estrechamiento brusco de la luz; sitio habitual de enterotomía para vaciar el colon.', 'Palpación rectal; exteriorización en la laparotomía para la enterotomía.', (SELECT id FROM cavidades WHERE codigo = 'abdominal'), (SELECT id FROM sistemas_anatomicos WHERE codigo = 'digestivo'), ARRAY['Dyce, Sack & Wensing 2018', 'Budras, Sack & Röck 2012', 'Auer & Stick, Equine Surgery (ed. reciente)']::text[], TRUE, ARRAY['irrigacion_drenaje', 'descripcion']::text[], 'ambos')
ON CONFLICT (ficha_id) DO UPDATE SET nombre = EXCLUDED.nombre, nombre_latino = EXCLUDED.nombre_latino, descripcion = EXCLUDED.descripcion, topografia = EXCLUDED.topografia, proyeccion_superficial = EXCLUDED.proyeccion_superficial, relaciones = EXCLUDED.relaciones, medios_de_fijacion = EXCLUDED.medios_de_fijacion, irrigacion_drenaje = EXCLUDED.irrigacion_drenaje, dimensiones = EXCLUDED.dimensiones, consideraciones_clinicas = EXCLUDED.consideraciones_clinicas, exploracion = EXCLUDED.exploracion, cavidad_id = EXCLUDED.cavidad_id, sistema_id = EXCLUDED.sistema_id, referencias = EXCLUDED.referencias, pendiente_validacion = EXCLUDED.pendiente_validacion, campos_pendientes = EXCLUDED.campos_pendientes, sexo_aplicable = EXCLUDED.sexo_aplicable;
VALUES ('ABD_COLON_DORSAL_IZQ', 'Colon dorsal izquierdo', 'Colon dorsale sinistrum', 'Segmento del colon mayor de diámetro reducido, con una sola tenia y sin saculaciones, que discurre cranealmente desde la flexura pélvica hasta la flexura diafragmática. Tras la flexura pélvica el colon pasa de ser saculado a liso.', 'Lado izquierdo, dorsal al colon ventral izquierdo.', 'Flanco izquierdo, en su tercio medio y ventral.', 'Ventralmente, el colon ventral izquierdo; dorsalmente, el yeyuno y el colon descendente; cranealmente, el estómago y el bazo.', 'Libre: solo lo une al colon ventral izquierdo un mesocolon corto.', 'Arteria cólica derecha y su anastomosis con la rama cólica (de la mesentérica craneal).', 'Diámetro menor que el de los colones ventrales; aumenta hacia craneal.', 'Participa en el desplazamiento dorsal izquierdo con atrapamiento nefroesplénico y en el vólvulo del colon mayor. Su movilidad permite que gire sobre su eje junto con el colon ventral izquierdo.', 'Palpación rectal; ecografía.', (SELECT id FROM cavidades WHERE codigo = 'abdominal'), (SELECT id FROM sistemas_anatomicos WHERE codigo = 'digestivo'), ARRAY['Dyce, Sack & Wensing 2018', 'Auer & Stick, Equine Surgery (ed. reciente)']::text[], TRUE, ARRAY['irrigacion_drenaje']::text[], 'ambos')
