VALUES ('ING_CORDON_ESPERMATICO', 'Cordón espermático y túnica vaginal', 'Funiculus spermaticus; tunica vaginalis', 'Conjunto de estructuras que suspenden el testículo y lo conectan con la cavidad abdominal, envueltas por la túnica vaginal (evaginación del peritoneo). Su longitud permite que el cremáster eleve y descienda el testículo.', 'Desde el anillo vaginal, a través del conducto inguinal, hasta el polo dorsal del testículo en el escroto.', 'Cuello del escroto y región inguinal.', 'Contiene el conducto deferente, la arteria testicular, el plexo pampiniforme, linfáticos y nervios; el músculo cremáster discurre fuera de la túnica vaginal.', 'Continuidad con el peritoneo en el anillo vaginal; ligamento de la cola del epidídimo distalmente.', 'Arteria testicular y plexo pampiniforme.', 'No aplica', 'Torsión del cordón espermático; base de las técnicas de castración abierta, cerrada y semicerrada (según se incida o no la túnica vaginal).', 'Palpación externa del cuello escrotal; ecografía Doppler.', (SELECT id FROM cavidades WHERE codigo = 'inguinal'), (SELECT id FROM sistemas_anatomicos WHERE codigo = 'reproductor'), ARRAY['Dyce, Sack & Wensing 2018', 'Auer & Stick, Equine Surgery (ed. reciente)']::text[], TRUE, ARRAY['descripcion']::text[], 'macho')
ON CONFLICT (ficha_id) DO UPDATE SET nombre = EXCLUDED.nombre, nombre_latino = EXCLUDED.nombre_latino, descripcion = EXCLUDED.descripcion, topografia = EXCLUDED.topografia, proyeccion_superficial = EXCLUDED.proyeccion_superficial, relaciones = EXCLUDED.relaciones, medios_de_fijacion = EXCLUDED.medios_de_fijacion, irrigacion_drenaje = EXCLUDED.irrigacion_drenaje, dimensiones = EXCLUDED.dimensiones, consideraciones_clinicas = EXCLUDED.consideraciones_clinicas, exploracion = EXCLUDED.exploracion, cavidad_id = EXCLUDED.cavidad_id, sistema_id = EXCLUDED.sistema_id, referencias = EXCLUDED.referencias, pendiente_validacion = EXCLUDED.pendiente_validacion, campos_pendientes = EXCLUDED.campos_pendientes, sexo_aplicable = EXCLUDED.sexo_aplicable;
VALUES ('ING_CONDUCTO_DEFERENTE', 'Conducto deferente', 'Ductus deferens', 'Conducto que transporta los espermatozoides desde la cola del epidídimo hasta la uretra. Termina en una ampolla bien desarrollada antes de desembocar en el colículo seminal.', 'De la cola del epidídimo asciende por el cordón espermático y el conducto inguinal, entra en el abdomen por el anillo vaginal, gira caudomedialmente en el pliegue genital, cruza dorsal al uréter y forma la ampolla dorsal al cuello vesical.', 'No aplica', 'Cordón espermático, uréter (al que cruza dorsalmente), vejiga urinaria y recto (dorsal a la ampolla).', 'Mesoducto deferente y pliegue genital.', 'Arteria del conducto deferente.', 'Fino en casi todo su trayecto; la ampolla tiene un diámetro mucho mayor.', 'La ampolla es palpable por vía rectal; su obstrucción (ampollas taponadas) produce eyaculados pobres en espermatozoides.', 'Palpación y ecografía transrectales de las ampollas.', (SELECT id FROM cavidades WHERE codigo = 'inguinal'), (SELECT id FROM sistemas_anatomicos WHERE codigo = 'reproductor'), ARRAY['Dyce, Sack & Wensing 2018', 'Budras, Sack & Röck 2012']::text[], TRUE, ARRAY['irrigacion_drenaje', 'consideraciones_clinicas']::text[], 'macho')
ON CONFLICT (ficha_id) DO UPDATE SET nombre = EXCLUDED.nombre, nombre_latino = EXCLUDED.nombre_latino, descripcion = EXCLUDED.descripcion, topografia = EXCLUDED.topografia, proyeccion_superficial = EXCLUDED.proyeccion_superficial, relaciones = EXCLUDED.relaciones, medios_de_fijacion = EXCLUDED.medios_de_fijacion, irrigacion_drenaje = EXCLUDED.irrigacion_drenaje, dimensiones = EXCLUDED.dimensiones, consideraciones_clinicas = EXCLUDED.consideraciones_clinicas, exploracion = EXCLUDED.exploracion, cavidad_id = EXCLUDED.cavidad_id, sistema_id = EXCLUDED.sistema_id, referencias = EXCLUDED.referencias, pendiente_validacion = EXCLUDED.pendiente_validacion, campos_pendientes = EXCLUDED.campos_pendientes, sexo_aplicable = EXCLUDED.sexo_aplicable;
VALUES ('ING_VASOS_TESTICULARES', 'Arteria testicular y plexo pampiniforme', 'Arteria testicularis; plexus pampiniformis', 'La arteria testicular, rama de la aorta abdominal, irriga el testículo y el epidídimo. Las venas testiculares forman alrededor de ella el plexo pampiniforme, que enfría la sangre arterial por intercambio de calor.', 'Nace de la aorta abdominal, desciende retroperitonealmente hasta el anillo vaginal y recorre el cordón espermático hasta el polo dorsal del testículo, donde el plexo es más voluminoso.', 'Cuello del escroto (plexo pampiniforme palpable).', 'Conducto deferente y túnica vaginal en el cordón espermático. El músculo cremáster queda fuera de la túnica vaginal, junto al cordón.', 'Mesorquio dentro del cordón espermático.', 'Las venas testiculares drenan a la vena cava caudal.', 'La arteria es fina; el plexo pampiniforme se ensancha cerca del polo dorsal del testículo.', 'Hemorragia tras la castración (ligadura o emasculación del cordón); varicocele (raro).', 'Ecografía Doppler del cordón espermático.', (SELECT id FROM cavidades WHERE codigo = 'inguinal'), (SELECT id FROM sistemas_anatomicos WHERE codigo = 'cardiovascular'), ARRAY['Dyce, Sack & Wensing 2018', 'Auer & Stick, Equine Surgery (ed. reciente)']::text[], TRUE, ARRAY['descripcion', 'irrigacion_drenaje', 'consideraciones_clinicas', 'dimensiones']::text[], 'macho')
