SELECT c.id, 'Practica 3D: Cavidades toracica, abdominal y region inguinal',
       'Exploracion de las visceras del equino con seleccion por clic y ficha anatomica.',
       '{"habilitado": true, "tema": "cavidades_equinas", "nivel": "intermedio", "script3d": "cavidades_equinas.py", "tiempoMinutos": 45, "objetivos": ["Identificar las visceras de las cavidades toracica y abdominal y de la region inguinal", "Relacionar cada estructura con su topografia y proyeccion superficial"], "instrucciones": ["Inicia el visor 3D de cavidades", "Haz clic en una estructura para ver su ficha", "Repite el clic en el mismo punto para llegar a estructuras profundas"], "escenario": {"titulo": "Cavidades del equino", "descripcion": "Exploracion guiada por capas"}}'::jsonb
FROM cursos c WHERE c.nombre = 'Anatomia Veterinaria Equina I'
AND NOT EXISTS (SELECT 1 FROM simulaciones s WHERE s.curso_id = c.id
                AND s.nombre = 'Practica 3D: Cavidades toracica, abdominal y region inguinal');

COMMIT;
